<script setup lang="ts">
// 起動時のロゴのアニメーション。文字を一筆ずつ描き、線を消しながら塗りを出す。最後に矢印が上下に動く。
// 時間はフレーム（60 コマ／秒）で書き、SPEED 倍で再生する。
const SPEED = 3
const FRAMES = 210
const FPS = 60

const emit = defineEmits<{ done: [] }>()
const leaving = ref(false)
let timer: ReturnType<typeof setTimeout> | undefined

function finish() {
    if (leaving.value) return
    leaving.value = true
    clearTimeout(timer)
    setTimeout(() => emit('done'), 250)
}

onMounted(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return emit('done')
    timer = setTimeout(finish, (FRAMES / FPS / SPEED) * 1000)
    window.addEventListener('keydown', finish, { once: true })
})

onBeforeUnmount(() => {
    clearTimeout(timer)
    window.removeEventListener('keydown', finish)
})
</script>

